// كتاب تجريبي من نوع «* متن» ثم «شرح:» (صفحات من «شرح العقيدة الواسطية» للعثيمين id=11250)
import fs from 'node:fs';
const P52 =
  'والجماعة، ولا يصدق الوصف على غيرهم أبدًا والكلمات تعتبر معانيها، فأهل السنة والجماعة هم السلف معتقدًا، حتى المتأخر إلى يوم القيامة إذا كان على طريقة النبي ﷺ وأصحابه، فإنه سلفي.\n* قوله: "وهو الإيمان بالله، وملائكته، وكتبه، ورسله، والبعث بعد الموت، والإيمان بالقدر خيره وشره".\nشرح:\nهذه العقيدة أصلها لنا النبي ﷺ في جواب جبريل حين سأل النبي ﷺ: ما الإسلام؟ ما الإيمان؟ ما الإحسان؟ متى الساعة؟ فالإيمان - قال له ـ: "أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشره" (١).\n"الإيمان بالله": الإيمان في اللغة: يقول كثير من الناس: إنه التصديق، فصدقت وآمنت معناهما لغة واحد، بل الإيمان في اللغة: الإقرار بالشيء عن تصديق به.\nإذا فالإيمان يتضمن معنى زائدًا على مجرد التصديق، وهو\n_________\n(١) رواه مسلم (٨) من حديث عمر بن الخطاب ﵁ في كتاب الإيمان/ باب بيان أركان الإيمان والإسلام.';
const P53 =
  'الإقرار والاعتراف المستلزم للقبول للأخبار والإذعان للأحكام.\n<span data-type="title" id=toc-20>الإيمان بالملائكة</span>النص بعد العنوان ملتصق به في المصدر.\n* قوله: "وملائكته".\nشرح:\nالملائكة جمع ملك، وأصل ملك: مألك، من الألوكة وهي الرسالة، وهم عالم غيبي خلقهم الله من نور.';
const P63 =
  '"وكتبه" أي: كتب الله التي أنزلها مع الرسل.\nولكل رسول كتاب، قال الله تعالى: ﴿لَقَدْ أَرْسَلْنَا رُسُلَنَا بِالْبَيِّنَاتِ وَأَنْزَلْنَا مَعَهُمُ الْكِتَابَ وَالْمِيزَانَ﴾ [الحديد: ٢٥]، وهذا يدل على أن كل رسول معه كتاب.\n* قوله: "ورسله".';
const P64 = 'شرح:\n"ورسله" أي: رسل الله، وهم الذين أوحى الله إليهم بالشرائع وأمرهم بتبليغها، وأولهم نوح وآخرهم محمد ﷺ.';
const pages = [P52, P53, P63, P64];
const meta = (i) => JSON.stringify({ headings: [], page_id: i, page: i + 50, vol: '1', book_name: 'شرح العقيدة الواسطية - العثيمين', author_name: 'ابن عثيمين' });
const book = {
  meta: { id: 11250, name: 'شرح العقيدة الواسطية - العثيمين', info: 'الكتاب: شرح العقيدة الواسطية\nالمؤلف: محمد بن صالح العثيمين (ت ١٤٢١هـ)' },
  indexes: { headings: [{ title: 'الإيمان بالملائكة', level: 2, page: 2 }], volume_bounds: { 1: [1, pages.length] }, page_map: pages.map((_, i) => `1,${i + 51}`) },
};
fs.writeFileSync(new URL('./book-star.json', import.meta.url), JSON.stringify({ book, pages: pages.map((text, i) => ({ page_id: i + 1, text, meta: meta(i + 1) })) }, null, 1));
console.log('star fixture pages:', pages.length);
